def fetch_if_missing(remote, local):
    import subprocess
    import tempfile
    import time
    import uuid
    from pathlib import Path

    local = Path(local)

    def validate(path):
        if not path.is_file():
            raise ValueError(f"Missing downloaded file: {path}")
        if path.suffix in (".bval", ".bvec"):
            values = np.loadtxt(path, ndmin=2)
            rows = 1 if path.suffix == ".bval" else 3
            if values.shape[0] != rows or values.shape[1] == 0 or not np.isfinite(values).all():
                raise ValueError(f"Invalid gradient table: {path}")
            if path.suffix == ".bval" and (values < 0).any():
                raise ValueError(f"Negative b-value: {path}")
            if path.suffix == ".bvec":
                bvals = np.loadtxt(local.with_suffix(".bval"), ndmin=2)
                if bvals.shape != (1, values.shape[1]) or not np.isfinite(bvals).all() or (bvals < 0).any():
                    raise ValueError(f"b-values and b-vectors do not match: {path}")
            return
        subprocess.run(
            ["mrstats", str(path), "-quiet", "-output", "count"],
            check=True, timeout=600, stdout=subprocess.DEVNULL,
        )

    if local.exists():
        try:
            validate(local)
        except (subprocess.CalledProcessError, ValueError) as error:
            quarantine = local.with_name(f"{local.name}.{uuid.uuid4().hex}.invalid")
            os.replace(local, quarantine)
            print(f"Invalid cache preserved at {quarantine}: {error}")
        else:
            print(f"Already exists and is valid, skipping: {local}")
            return

    for attempt in range(4):
        try:
            with tempfile.TemporaryDirectory(dir=local.parent) as directory:
                temporary = Path(directory) / local.name
                subprocess.run(
                    ["osf", "-p", "y2dq4", "fetch", remote, str(temporary)],
                    check=True, timeout=600,
                )
                validate(temporary)
                os.replace(temporary, local)
            return
        except (subprocess.CalledProcessError, subprocess.TimeoutExpired, ValueError) as error:
            if attempt == 3:
                raise RuntimeError(
                    f"Failed to fetch {remote} to {local} after 4 attempts"
                ) from error
            delay = 5 * 2 ** attempt
            print(f"Download {remote} failed: {error}. Retrying in {delay}s.")
            time.sleep(delay)

